<?php use FilamentManager\Core\View; ?>
<h1><?= View::t('storage_locations') ?></h1><div class="grid"><section class="card"><h2><?= View::t('new_location') ?></h2><form method="post" action="<?= View::e($basePath) ?>/locations"><?= View::csrf() ?><label><?= View::t('name') ?><input name="name" required maxlength="120"></label><label><?= View::t('code') ?><input name="code" maxlength="60"></label><label><?= View::t('parent_location') ?><select name="parent_id"><option value="">—</option><?php foreach($locations as $l): ?><option value="<?= View::e($l['id']) ?>"><?= View::e($l['name']) ?></option><?php endforeach; ?></select></label><label><?= View::t('description') ?><input name="description" maxlength="255"></label><button><?= View::t('save') ?></button></form></section><section><div class="table-wrap"><table><thead><tr><th><?= View::t('name') ?></th><th><?= View::t('code') ?></th><th><?= View::t('parent_location') ?></th><th><?= View::t('spool_count') ?></th><th></th></tr></thead><tbody><?php foreach($locations as $l): ?><tr><td><?= View::e($l['name']) ?></td><td><?= View::e($l['code']) ?></td><td><?= View::e($l['parent_name']??'—') ?></td><td><?= View::e($l['spool_count']) ?></td><td><?php if(in_array($app->auth()->user()['role'],['admin','manager'],true)): ?><form method="post" action="<?= View::e($basePath) ?>/locations/<?= View::e($l['id']) ?>/delete"><?= View::csrf() ?><button class="link-button"><?= View::t('delete') ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></div>
